"use strict";(self.webpackChunkcoursesmith_site=self.webpackChunkcoursesmith_site||[]).push([["3132"],{9714(e,t,n){n.r(t),n.d(t,{metadata:()=>o,default:()=>u,frontMatter:()=>i,contentTitle:()=>d,toc:()=>h,assets:()=>l});var o=JSON.parse('{"id":"m4-model-effort-cost/lesson","title":"Model, Effort & Cost Engineering","description":"In Module 3 you gave the agent a durable operating contract and taught it to collect evidence with provenance. Every fact it produced could be traced back to where it came from. This module extends that same discipline to the agent\'s own work: the run itself is evidence, and right now you cannot see it.","source":"@site/docs/m4-model-effort-cost/lesson.md","sourceDirName":"m4-model-effort-cost","slug":"/m4-model-effort-cost/lesson","permalink":"/306-agentic-devops-claude/docs/m4-model-effort-cost/lesson","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":1,"frontMatter":{"sidebar_position":1,"title":"Model, Effort & Cost Engineering"},"sidebar":"courseSidebar","previous":{"title":"Deep Dive (Part 2)","permalink":"/306-agentic-devops-claude/docs/m3-context-evidence-memory/deep-dive"},"next":{"title":"Lab: Build the Agent Run Ledger","permalink":"/306-agentic-devops-claude/docs/m4-model-effort-cost/lab"}}'),s=n(4848),a=n(8453),r=n(7684);let i={sidebar_position:1,title:"Model, Effort & Cost Engineering"},d="Model, Effort & Cost Engineering",l={},h=[{value:"Why model choice is a staffing decision",id:"why-model-choice-is-a-staffing-decision",level:2},{value:"Effort: how hard the same person works",id:"effort-how-hard-the-same-person-works",level:2},{value:"Mapping models and effort to roles",id:"mapping-models-and-effort-to-roles",level:2},{value:"The run is evidence you cannot yet see",id:"the-run-is-evidence-you-cannot-yet-see",level:2},{value:"OpenTelemetry: the agent&#39;s instrumentation",id:"opentelemetry-the-agents-instrumentation",level:2},{value:"The Agent Run Ledger",id:"the-agent-run-ledger",level:2},{value:"Budgets, alerts, and regression checks",id:"budgets-alerts-and-regression-checks",level:2},{value:"What you&#39;ll do in the lab",id:"what-youll-do-in-the-lab",level:2}];function c(e){let t={admonition:"admonition",em:"em",h1:"h1",h2:"h2",header:"header",li:"li",mermaid:"mermaid",p:"p",strong:"strong",table:"table",tbody:"tbody",td:"td",th:"th",thead:"thead",tr:"tr",ul:"ul",...(0,a.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(t.header,{children:(0,s.jsx)(t.h1,{id:"model-effort--cost-engineering",children:"Model, Effort & Cost Engineering"})}),"\n",(0,s.jsx)(t.p,{children:"In Module 3 you gave the agent a durable operating contract and taught it to collect evidence with provenance. Every fact it produced could be traced back to where it came from. This module extends that same discipline to the agent's own work: the run itself is evidence, and right now you cannot see it."}),"\n",(0,s.jsx)(r.A,{src:"decks/m4-model-effort-cost.html",title:"M4 \u2014 Model, Effort & Cost Engineering"}),"\n",(0,s.jsxs)(t.p,{children:["Here is the gap. When you ask Claude Code to diagnose the readiness bug, you get an answer \u2014 but you have no record of ",(0,s.jsx)(t.em,{children:"how much that answer cost"}),". Which model ran it. What effort level. How many tokens went in and came back. How many tool calls it made, how many you had to approve, how many times you had to step in and correct it. On one task that opacity is fine. Across a platform team running the agent dozens of times a day, it is the difference between a tool you can budget for and a line item that surprises you at the end of the month. You already meter your infrastructure \u2014 CPU, memory, request rates. The agent is now part of your infrastructure, and it is unmetered."]}),"\n",(0,s.jsxs)(t.p,{children:["This module closes that gap in two moves. First, you learn to make ",(0,s.jsx)(t.strong,{children:"model and effort deliberate choices"})," rather than defaults you never think about \u2014 staffing decisions, where you pick the right capability for the job instead of sending your most expensive reasoner to write a changelog. Second, you learn to ",(0,s.jsx)(t.strong,{children:"turn every agent run into a measured, auditable record"}),' \u2014 the Agent Run Ledger \u2014 so that "how much did that cost" has an answer you can point to, the same way "is orders-api ready" had an answer in Module 1.']}),"\n",(0,s.jsx)(t.h2,{id:"why-model-choice-is-a-staffing-decision",children:"Why model choice is a staffing decision"}),"\n",(0,s.jsx)(t.p,{children:"Think about how you staff a real team. You do not put your principal engineer on the task of renaming a variable across forty files, and you do not hand a critical production migration to the intern on their first week. You match the person to the job by four things: how capable they need to be, how fast you need it, what it costs to occupy their time, and how expensive a mistake would be. A rename is cheap to get wrong and cheap to fix, so you give it to whoever is free. A migration that could corrupt the orders database is expensive to get wrong, so you give it to someone whose judgment you trust and you have them double-check."}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Analogy:"}),' choosing a model is hiring for a shift. Each model is a candidate with a different r\xe9sum\xe9 \u2014 one is brilliant and expensive and deliberate, one is fast and cheap and good enough for routine work, one sits in the middle. You are not looking for "the best" in the abstract; you are looking for the right fit for ',(0,s.jsx)(t.em,{children:"this"})," task, given what it costs you to be wrong. Sending Opus to summarize a log file is like flying in a staff engineer to reset someone's password. It works, and you overpaid for it."]}),"\n",(0,s.jsx)(t.p,{children:"Claude Code lets you choose the model per session, and the models sort roughly along the capability-versus-cost line:"}),"\n",(0,s.jsxs)(t.table,{children:[(0,s.jsx)(t.thead,{children:(0,s.jsxs)(t.tr,{children:[(0,s.jsx)(t.th,{children:"Model"}),(0,s.jsx)(t.th,{children:"Relative strength"}),(0,s.jsx)(t.th,{children:"Relative cost"}),(0,s.jsx)(t.th,{children:"Fits"})]})}),(0,s.jsxs)(t.tbody,{children:[(0,s.jsxs)(t.tr,{children:[(0,s.jsx)(t.td,{children:"Opus"}),(0,s.jsx)(t.td,{children:"Highest capability, deepest judgment"}),(0,s.jsx)(t.td,{children:"Highest"}),(0,s.jsx)(t.td,{children:"Architecture, security review, complex multi-file changes, ambiguous debugging"})]}),(0,s.jsxs)(t.tr,{children:[(0,s.jsx)(t.td,{children:"Sonnet"}),(0,s.jsx)(t.td,{children:"Strong, balanced, the sensible default"}),(0,s.jsx)(t.td,{children:"Middle"}),(0,s.jsx)(t.td,{children:"Most investigation, routine implementation, day-to-day ops work"})]}),(0,s.jsxs)(t.tr,{children:[(0,s.jsx)(t.td,{children:"Haiku"}),(0,s.jsx)(t.td,{children:"Fast, capable of mechanical work"}),(0,s.jsx)(t.td,{children:"Lowest"}),(0,s.jsx)(t.td,{children:"Summaries, changelogs, formatting, high-volume simple classification"})]})]})]}),"\n",(0,s.jsx)(t.p,{children:"The pricing gap between the tiers is large \u2014 the most capable model costs several times the cheapest per token \u2014 so the choice is not cosmetic. It compounds. A task you run once a day at the wrong tier is a rounding error; the same task run by every engineer on every branch, all day, is a budget line."}),"\n",(0,s.jsx)(t.admonition,{title:"The models change; the reasoning does not",type:"note",children:(0,s.jsxs)(t.p,{children:['Model names and prices move over time \u2014 new tiers ship, prices shift. Do not memorize a specific model ID as "the cheap one." Memorize the ',(0,s.jsx)(t.em,{children:"decision"}),": capability, latency, price, failure cost. When the lineup changes, you re-run the same four-way judgment against the new options. The staffing logic outlives any particular roster."]})}),"\n",(0,s.jsx)(t.h2,{id:"effort-how-hard-the-same-person-works",children:"Effort: how hard the same person works"}),"\n",(0,s.jsxs)(t.p,{children:["Model is ",(0,s.jsx)(t.em,{children:"who"})," you assign. ",(0,s.jsx)(t.strong,{children:"Effort"})," is ",(0,s.jsx)(t.em,{children:"how hard you ask them to think"})," about it. The same engineer can glance at a one-line fix or spend an afternoon reasoning through a subtle concurrency bug \u2014 and you would not want them spending the afternoon on the one-liner, or glancing at the concurrency bug. Effort is that dial, applied to the model you already chose."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Analogy:"}),' effort is the difference between "give me your gut read" and "go away and think about this properly." For "which of these three log lines is the error," the gut read is correct and instant, and asking for a deep analysis just burns time and money to arrive at the same place. For "why does this only fail under load after a deploy," the gut read is a guess, and you actually want the deliberate, show-your-working version. Turning the dial up buys you more reasoning \u2014 more tokens spent thinking before acting \u2014 which costs more and takes longer. Turning it down buys speed and thrift at the price of depth.']}),"\n",(0,s.jsx)(t.p,{children:"The two dials interact, and that is the whole art of it:"}),"\n",(0,s.jsx)(t.mermaid,{value:'flowchart TD\n    TASK["A task arrives"] --\x3e Q1{"How much does a<br/>wrong answer cost?"}\n    Q1 --\x3e|"cheap to get wrong<br/>(changelog, summary)"| CHEAP["Cheaper model,<br/>lower effort"]\n    Q1 --\x3e|"expensive to get wrong<br/>(prod migration, security)"| Q2{"Does it need deep<br/>reasoning or just<br/>capability?"}\n    Q2 --\x3e|"routine but important"| MID["Balanced model,<br/>medium effort"]\n    Q2 --\x3e|"ambiguous, high-stakes"| DEAR["Most capable model,<br/>high effort"]\n    style CHEAP fill:#e8f5e9,stroke:#388e3c\n    style MID fill:#fff3e0,stroke:#f57c00\n    style DEAR fill:#e3f2fd,stroke:#1976d2'}),"\n",(0,s.jsxs)(t.p,{children:["A cheap model at high effort and an expensive model at low effort are both real, sensible configurations \u2014 they just suit different tasks. The failure mode is running ",(0,s.jsx)(t.em,{children:"everything"})," at the top-right corner because you never thought about it. That is not caution; it is paying for maximum reasoning on tasks that never needed it."]}),"\n",(0,s.jsx)(t.h2,{id:"mapping-models-and-effort-to-roles",children:"Mapping models and effort to roles"}),"\n",(0,s.jsxs)(t.p,{children:["The staffing analogy gets concrete when you stop thinking about individual tasks and start thinking about ",(0,s.jsx)(t.strong,{children:"roles"}),". In Module 5 you will split agent work into distinct jobs, and later modules give those jobs to separate subagents. Each role has a characteristic capability profile, and that profile tells you how to staff it:"]}),"\n",(0,s.jsx)(t.mermaid,{value:'flowchart LR\n    subgraph ROLES["The four common agent roles"]\n      INV["Investigator<br/>reads logs, traces, metrics<br/>\u2192 finds the problem"]\n      IMP["Implementer<br/>writes the code<br/>\u2192 makes the change"]\n      REV["Reviewer<br/>audits the change<br/>\u2192 judges it safe"]\n      SUM["Summarizer<br/>writes the status/changelog<br/>\u2192 reports what happened"]\n    end\n    INV --\x3e INVM["Balanced model,<br/>medium effort"]\n    IMP --\x3e IMPM["Balanced for routine,<br/>top-tier for complex"]\n    REV --\x3e REVM["Top-tier model,<br/>high effort"]\n    SUM --\x3e SUMM["Cheapest model,<br/>low effort"]\n    style INVM fill:#fff3e0,stroke:#f57c00\n    style IMPM fill:#fff3e0,stroke:#f57c00\n    style REVM fill:#e3f2fd,stroke:#1976d2\n    style SUMM fill:#e8f5e9,stroke:#388e3c'}),"\n",(0,s.jsxs)(t.ul,{children:["\n",(0,s.jsxs)(t.li,{children:[(0,s.jsx)(t.strong,{children:"Investigator"})," \u2014 reads evidence and reasons toward a root cause. It needs genuine reasoning but rarely the deepest tier; a balanced model at medium effort finds the readiness bug without overpaying. Send Opus here only when the investigation is genuinely ambiguous."]}),"\n",(0,s.jsxs)(t.li,{children:[(0,s.jsx)(t.strong,{children:"Implementer"})," \u2014 turns a decision into a code change. Routine changes (add a field, fix a path) are fine on a balanced model; a complex multi-file refactor with subtle interactions is where the top tier earns its price, because a wrong implementation is expensive to catch and fix."]}),"\n",(0,s.jsxs)(t.li,{children:[(0,s.jsx)(t.strong,{children:"Reviewer"})," \u2014 the one role where you almost always pay for the best. A reviewer's whole job is judgment: catching the subtle bug, the security implication, the thing that looks fine and is not. This is your senior engineer signing off on the migration. Underpaying here is a false economy \u2014 the cost of the review is tiny next to the cost of the defect it should have caught."]}),"\n",(0,s.jsxs)(t.li,{children:[(0,s.jsx)(t.strong,{children:"Summarizer"})," \u2014 mechanical restatement of work that already happened. Writing a changelog from a diff, a status line from a run. This is the cheapest model at the lowest effort, and paying more for it is pure waste."]}),"\n"]}),"\n",(0,s.jsxs)(t.p,{children:['The reviewer/summarizer split is the clearest illustration of the principle. Both are "read something and produce text," but one is a judgment call where mistakes are costly and the other is transcription where mistakes are cheap and obvious. Same shape of task, opposite staffing \u2014 because the ',(0,s.jsx)(t.em,{children:"failure cost"})," differs, not the surface activity."]}),"\n",(0,s.jsx)(t.h2,{id:"the-run-is-evidence-you-cannot-yet-see",children:"The run is evidence you cannot yet see"}),"\n",(0,s.jsx)(t.p,{children:'Now the second half of the module. You have learned to choose models and effort deliberately \u2014 but a choice you cannot measure is a choice you cannot defend or improve. If someone asks "why is our agent spend up 40% this month," or "did switching the reviewer to Opus actually catch more bugs, or just cost more," you need data about the runs themselves. Right now that data exists \u2014 it is generated on every run \u2014 but it evaporates the moment the session ends.'}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Analogy:"}),' a Claude Code session with no telemetry is a contractor who does good work and hands you no invoice, no timesheet, no materials list. You can see the finished wall. You cannot see that it took nine hours, used three trips to the supplier, and that they had to redo the wiring twice because the first plan was wrong. When the bill is a flat "trust me," you cannot budget, you cannot compare two contractors, and you cannot spot the job that quietly cost triple. The work being good is not the same as the work being ',(0,s.jsx)(t.em,{children:"accountable"}),"."]}),"\n",(0,s.jsx)(t.p,{children:"This connects directly to Module 3's evidence contracts. There, you insisted that any fact the agent produced come with provenance \u2014 source, time, uncertainty \u2014 so you could trust it. The agent's own execution deserves the same treatment. Every run produces facts: which model, what effort, how many tokens, what it cost, how many tools it called, how many permissions you approved or denied, how many times a human intervened. Those facts are operational evidence about the agent as a system, and like all evidence they are worthless if they evaporate. You need to capture them, with provenance, in a durable record."}),"\n",(0,s.jsx)(t.h2,{id:"opentelemetry-the-agents-instrumentation",children:"OpenTelemetry: the agent's instrumentation"}),"\n",(0,s.jsxs)(t.p,{children:["The mechanism for capturing that evidence already exists and is a standard you likely use elsewhere in your stack: ",(0,s.jsx)(t.strong,{children:"OpenTelemetry"}),". Claude Code can emit telemetry about its own operation \u2014 metrics like token counts and cost, and events like each API request and tool decision \u2014 over the OpenTelemetry protocol (OTLP), to a collector you run."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Analogy:"})," OpenTelemetry is the standardized diagnostic port on the agent. Modern vehicles all expose an OBD-II port: whatever the make, you plug in a standard reader and get standard readings \u2014 speed, fuel, error codes. You do not build a custom sensor rig per car. OpenTelemetry is that port for software: Claude Code emits its readings in the standard format, and any standard collector can receive them. Because it is the same protocol your services already speak, the agent's telemetry lands in the same kind of pipeline as everything else you operate \u2014 it is not a special snowflake tool, it is one more instrumented process."]}),"\n",(0,s.jsxs)(t.p,{children:["You turn it on with environment variables \u2014 an enable flag and an exporter target \u2014 and Claude Code begins emitting. The readings flow to a ",(0,s.jsx)(t.strong,{children:"collector"}),": a small local process that receives OTLP data and writes it somewhere you can read. In the lab you run a lightweight collector that writes the telemetry to a file, and for the no-collector case Claude Code can print its telemetry straight to the console. Either way, the run stops being invisible."]}),"\n",(0,s.jsx)(t.mermaid,{value:'flowchart LR\n    CC["Claude Code session<br/>(does the work)"] --\x3e|"OTLP: metrics + events<br/>tokens, cost, tools, decisions"| COL["Local OTel collector<br/>(receives, writes to file)"]\n    COL --\x3e ART["Telemetry artifact<br/>(durable, parseable)"]\n    ART --\x3e LEDGER["Agent Run Ledger<br/>(one row per run)"]\n    style CC fill:#e3f2fd,stroke:#1976d2\n    style COL fill:#fff3e0,stroke:#f57c00\n    style LEDGER fill:#e8f5e9,stroke:#388e3c'}),"\n",(0,s.jsx)(t.h2,{id:"the-agent-run-ledger",children:"The Agent Run Ledger"}),"\n",(0,s.jsxs)(t.p,{children:["Raw telemetry is necessary but not yet useful \u2014 it is a stream of data points and events, not an answer. The final step is to turn it into a ",(0,s.jsx)(t.strong,{children:"ledger"}),": one row per run, each row summarizing that run in the terms you actually care about."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Analogy:"}),' the ledger is the itemized invoice you build from the contractor\'s raw timesheet. The timesheet has every clock-in and clock-out and supply run; the invoice rolls it up into "job X: 9 hours, $340 materials, total $Y." You want the invoice, because that is the unit you budget and compare in. Raw telemetry is the timesheet. The Agent Run Ledger is the invoice \u2014 and because it is built from the real timesheet, not estimated, you can trust it.']}),"\n",(0,s.jsx)(t.p,{children:"Each ledger row captures a run as an auditable record:"}),"\n",(0,s.jsxs)(t.table,{children:[(0,s.jsx)(t.thead,{children:(0,s.jsxs)(t.tr,{children:[(0,s.jsx)(t.th,{children:"Field"}),(0,s.jsx)(t.th,{children:"What it tells you"})]})}),(0,s.jsxs)(t.tbody,{children:[(0,s.jsxs)(t.tr,{children:[(0,s.jsx)(t.td,{children:"Session ID, timestamp, duration"}),(0,s.jsx)(t.td,{children:"Which run, when, how long on the wall clock"})]}),(0,s.jsxs)(t.tr,{children:[(0,s.jsx)(t.td,{children:"Model + effort"}),(0,s.jsx)(t.td,{children:"How it was staffed \u2014 the choice you now made deliberately"})]}),(0,s.jsxs)(t.tr,{children:[(0,s.jsx)(t.td,{children:"Input / output tokens"}),(0,s.jsx)(t.td,{children:"The size of the work in the unit you are billed in"})]}),(0,s.jsxs)(t.tr,{children:[(0,s.jsx)(t.td,{children:"Estimated cost"}),(0,s.jsx)(t.td,{children:"Tokens turned into money, the number finance asks about"})]}),(0,s.jsxs)(t.tr,{children:[(0,s.jsx)(t.td,{children:"Tool calls (count, types, failures)"}),(0,s.jsxs)(t.td,{children:["How much the agent ",(0,s.jsx)(t.em,{children:"did"}),", and where it stumbled"]})]}),(0,s.jsxs)(t.tr,{children:[(0,s.jsx)(t.td,{children:"Permission decisions (approved / denied)"}),(0,s.jsx)(t.td,{children:"How much the boundary from Module 2 was exercised"})]}),(0,s.jsxs)(t.tr,{children:[(0,s.jsx)(t.td,{children:"Human interventions"}),(0,s.jsx)(t.td,{children:"How autonomous the run actually was"})]})]})]}),"\n",(0,s.jsxs)(t.p,{children:['Read across a row and you can answer "what did this run cost and how did it behave." Read ',(0,s.jsx)(t.em,{children:"down"})," a column across many rows and you can answer the questions that matter at team scale: which tasks cost the most, whether a model change paid off, whether a run that used to be cheap suddenly is not."]}),"\n",(0,s.jsx)(t.h2,{id:"budgets-alerts-and-regression-checks",children:"Budgets, alerts, and regression checks"}),"\n",(0,s.jsxs)(t.p,{children:["A ledger you only read after the fact is a post-mortem tool. Its real power is that it lets you set ",(0,s.jsx)(t.strong,{children:"expectations in advance"})," and get told when reality diverges \u2014 the same instinct that makes you alert on latency or error rate for your services."]}),"\n",(0,s.jsx)(t.p,{children:"Three controls fall straight out of having the data:"}),"\n",(0,s.jsxs)(t.ul,{children:["\n",(0,s.jsxs)(t.li,{children:[(0,s.jsx)(t.strong,{children:"Per-role budgets."})," Once you know a summarizer run costs a fraction of a cent and a reviewer run costs meaningfully more, you can set a token or cost ceiling per role and flag any run that blows past it. A summarizer that suddenly costs like a reviewer is either misconfigured or being handed the wrong work."]}),"\n",(0,s.jsxs)(t.li,{children:[(0,s.jsx)(t.strong,{children:"Spend alerts."}),' A simple threshold on a run \u2014 "flag any single run over N tokens" \u2014 catches the runaway before it becomes a bill. This is the agent equivalent of an alert on a query that suddenly scans the whole table.']}),"\n",(0,s.jsxs)(t.li,{children:[(0,s.jsx)(t.strong,{children:"Model regression checks."})," The sharpest use of the ledger over time. If a task that reliably cost $0.10 last week now costs $1.00, ",(0,s.jsx)(t.em,{children:"something changed"})," \u2014 a prompt got bloated, the effort got bumped, the wrong model got selected, the task got harder. You cannot notice that drift without a baseline, and the ledger is the baseline. This is exactly the Module 1 diagnose\u2192change\u2192verify loop applied to cost: you have a measured expectation, you detect the deviation, you investigate the cause."]}),"\n"]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Analogy:"})," this is a cost SLO for the agent. You already run SLOs on the systems you operate \u2014 a latency budget, an error budget \u2014 and you alert when the service spends its budget faster than it should. A per-run token budget is the same contract applied to the agent: a stated expectation, and an alarm when it is breached. The agent is a system you operate now, so it gets operated on like one."]}),"\n",(0,s.jsx)(t.h2,{id:"what-youll-do-in-the-lab",children:"What you'll do in the lab"}),"\n",(0,s.jsxs)(t.p,{children:["You will make the agent's work visible and turn it into a ledger you can act on. You will stand up a local OpenTelemetry collector; configure Claude Code to export its telemetry to it; run a real diagnostic task against Northstar and capture the run's telemetry; build the Agent Run Ledger script that parses that telemetry into a structured per-run record; run the ",(0,s.jsx)(t.em,{children:"same"})," task at different model and effort settings and compare the token, cost, and behavior differences side by side in the ledger; and finally set a per-run budget alert that flags a run for exceeding a token threshold \u2014 a regression check you could put in front of every agent run."]}),"\n",(0,s.jsxs)(t.p,{children:["Module 3 gave the agent's ",(0,s.jsx)(t.em,{children:"findings"})," provenance. This module gives the agent's ",(0,s.jsx)(t.em,{children:"own work"}),' provenance \u2014 a measured, auditable record of every run. By the end, "how much did that cost, and was it staffed right" is a question you can answer from data, not a shrug. The Deep Dive then widens the lens to the two separate budgets every agentic ops team runs at once: what the infrastructure costs, and what running the agents that manage it costs.']})]})}function u(e={}){let{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(c,{...e})}):c(e)}},7684(e,t,n){n.d(t,{A:()=>a});var o=n(4848);n(6540);var s=n(6497);function a({src:e,title:t="Slides"}){let n=(0,s.Ay)(e);return(0,o.jsxs)("div",{className:"deck_nWXz",children:[(0,o.jsxs)("div",{className:"bar_dOoE",children:[(0,o.jsxs)("span",{className:"label_ZSLR",children:["\u25B6 ",t]}),(0,o.jsx)("a",{className:"full_PrDQ",href:n,target:"_blank",rel:"noopener noreferrer",children:"Open fullscreen \u2197"})]}),(0,o.jsx)("div",{className:"frame_M4DO",children:(0,o.jsx)("iframe",{src:n,title:t,loading:"lazy",allowFullScreen:!0})})]})}},8453(e,t,n){n.d(t,{R:()=>r,x:()=>i});var o=n(6540);let s={},a=o.createContext(s);function r(e){let t=o.useContext(a);return o.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function i(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:r(e.components),o.createElement(a.Provider,{value:t},e.children)}}}]);